// Three ways in: the daily run, /plan from Telegram, a button under a proposal.
// Button data: s|<e schedule, a another slot, x skip>|<key>|<start in minutes since 1970>
const u = $input.first().json.update;
if (!u) return [{ json: { mode: 'run' } }];
const cq = u.callback_query;
if (!cq) return [{ json: { mode: 'plan' } }];
const m = String(cq.data || '').match(/^s\|([eax])\|([^|]+)\|(\d+)$/);
if (!m) return [];
return [{ json: { mode: 'callback', action: m[1], key: m[2], startMin: Number(m[3]),
  queryId: cq.id, chatId: cq.message.chat.id, messageId: cq.message.message_id } }];

// Values from the data table codebot_settings
const setting = (k, fallback) => {
  const v = String($input.all().map(i => i.json).find(r => r.key === k)?.value ?? '').trim() || fallback;
  if (!v) throw new Error(`${k} is missing in codebot_settings`);
  return v;
};
const timezone = setting('timezone');
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`timezone in codebot_settings is not a valid IANA time zone: ${timezone}`);
// ==== ADJUST HERE ====
return [{ json: {
  CHAT_ID: setting('telegram_chat_id'),
  CALENDAR_ID: setting('calendar_id'),   // the events are created here
  TIMEZONE: timezone,
  // Busy is whatever is in any of your Google calendars. List calendars here (ID or name)
  // that should not count as busy, e.g. a shared calendar.
  IGNORE_CALENDARS: [],

  // When a planning session may take place: any number of time windows [from, to] per weekday.
  // The session lies entirely within the window. An empty list means: never on that day.
  PLANNING_TIMES: {
    mon: [['19:00', '21:30']],
    tue: [['19:00', '21:30']],
    wed: [['19:00', '21:30']],
    thu: [['19:00', '21:30']],
    fri: [['19:00', '21:30']],
    sat: [],
    sun: [],
  },
  PLANNING_MINUTES: 60,                 // length of a planning session
  GRID_MINUTES: 30,                     // possible start times within the window: every 30 minutes
  HORIZON_DAYS: 14,                     // how far ahead a slot is proposed
  LEAD_HOURS: 2,                        // at the earliest this many hours from now
  SESSION_LOOKAHEAD_DAYS: 90,           // how far ahead an already scheduled planning session counts; then there is no proposal

  STATUS: ['Active', 'Waiting'],        // only projects with this status get proposals
  // If there is no open ticket with this label, the project needs planning
  READY_LABEL: setting('ready_label', 'ready-for-agent'),

  REPROPOSE_DAYS: 3,                    // the daily run proposes for the same project again after this many days at the earliest
  SKIP_DAYS: 7,                         // after “Skip”, this many days of quiet; /plan always proposes
}}];

// One item per calendar from the calendar list of the Google account, without those in IGNORE_CALENDARS.
// Your own calendar (CALENDAR_ID) is always included, even if the list was not readable.
const cfg = $('Config').first().json;
const r = $input.first().json;
const own = String(cfg.CALENDAR_ID ?? '').trim();
const ignored = new Set((cfg.IGNORE_CALENDARS || []).map(s => String(s).trim()));
const list = r.statusCode === 200 ? (r.body?.items || []) : null;
const cals = (list || []).filter(c => !c.deleted && c.id !== own && !ignored.has(c.id) && !ignored.has(c.summaryOverride || c.summary))
  .map(c => ({ calendarId: c.id, name: c.summaryOverride || c.summary || c.id }));
cals.unshift({ calendarId: own, name: 'own calendar' });
const listError = list ? '' : `HTTP ${r.statusCode ?? '?'}`;
return cals.map(c => ({ json: { ...c, listError } }));

// Per repo in codebot_projects: number of open tickets with READY_LABEL
const cfg = $('Config').first().json;
const rows = $('Projects').all().map(i => i.json).filter(r => r.key && cfg.STATUS.includes(r.status));
const repos = [...new Set(rows.map(r => String(r.repo || '').trim()).filter(r => /^[\w.-]+\/[\w.-]+$/.test(r)))];
if (!repos.length) return [{ json: { query: 'query { viewer { login } }', repos } }];
const parts = repos.map((r, i) => {
  const [o, n] = r.split('/');
  return `  r${i}: repository(owner: "${o}", name: "${n}") { nameWithOwner ready: issues(states: OPEN, labels: ["${cfg.READY_LABEL}"]) { totalCount } }`;
});
return [{ json: { query: `query {\n${parts.join('\n')}\n}`, repos } }];

// Returns Telegram calls (kind: 'tg') and at most one calendar event (kind: 'event').
const cfg = $('Config').first().json;
const inp = $('Input').first().json;
const tz = cfg.TIMEZONE;
const now = DateTime.now().setZone(tz);
const token = $('Settings').all().map(i => i.json).find(r => r.key === 'telegram_bot_token')?.value;
if (!token) throw new Error('telegram_bot_token is missing in codebot_settings');
const api = m => `https://api.telegram.org/bot${String(token).trim()}/${m}`;
const tg = (method, payload) => ({ json: { kind: 'tg', url: api(method), payload } });
const info = text => tg('sendMessage', { chat_id: cfg.CHAT_ID, text, link_preview_options: { is_disabled: true } });
const sd = $getWorkflowStaticData('global');
sd.pause = sd.pause || {};

// --- Calendars (all of the Google account): busy times and days with a planning session
// One response per calendar, in the order of Select calendars. Your own calendar must be readable, the others need not be.
const selected = $('Select calendars').all().map(i => i.json);
const calItems = [], unreadable = [];
let calError = !String(cfg.CALENDAR_ID ?? '').trim() ? 'CALENDAR_ID is missing in Config' : '';
$('Calendar: Events').all().map(i => i.json).forEach((r, i) => {
  const c = selected[i] || {};
  if (r.statusCode === 200) calItems.push(...(r.body?.items || []));
  else if (i === 0) calError = calError || `HTTP ${r.statusCode ?? '?'}${r.body?.error?.message ? ': ' + r.body.error.message : ''}`;
  else unreadable.push(c.name || c.calendarId);
});
const listError = selected[0]?.listError || '';
const events = calItems.filter(e => e.id && e.status !== 'cancelled');
// If the event was edited in Google, the description comes back as HTML: the key then ends before the next tag
const eventKey = e => (String(e.description || '').match(/codebot-key:(?:\s|&nbsp;)*([^\s<&]+)/) || [])[1] || '';
const busy = [];
for (const e of events) {
  if (e.transparency === 'transparent') continue;
  if (e.start?.dateTime) busy.push([DateTime.fromISO(e.start.dateTime), DateTime.fromISO(e.end.dateTime)]);
  else if (e.start?.date) busy.push([DateTime.fromISO(e.start.date, { zone: tz }), DateTime.fromISO(e.end.date, { zone: tz })]);
}
const sessions = events.filter(e => eventKey(e).startsWith('codebot-plan:') && e.start?.dateTime);
const sessionDays = new Set(sessions.map(e => DateTime.fromISO(e.start.dateTime).setZone(tz).toISODate()));

// --- Repos with a future planning session: Calendar: Sessions reads your own calendar further ahead than the horizon
const sr = $('Calendar: Sessions').first().json;
if (sr.statusCode !== 200) calError = calError || `HTTP ${sr.statusCode ?? '?'}${sr.body?.error?.message ? ': ' + sr.body.error.message : ''}`;
const ahead = (sr.body?.items || []).filter(e => e.id && e.status !== 'cancelled' && eventKey(e).startsWith('codebot-plan:') && e.start?.dateTime);
const planned = new Set([...sessions, ...ahead].filter(e => DateTime.fromISO(e.start.dateTime) > now).map(e => eventKey(e).slice('codebot-plan:'.length).toLowerCase()));

// --- Projects and their need for planning
const all = $('Projects').all().map(i => i.json).filter(r => r.key)
  .map(r => ({ key: String(r.key), name: r.name || r.key, status: r.status, prio: r.priority || 'Medium', repo: String(r.repo || '').trim() }));
const gh = $('GitHub').first().json;
const repoData = {};
for (const r of Object.values(gh.data || {})) if (r?.nameWithOwner) repoData[r.nameWithOwner.toLowerCase()] = r;
const need = p => {
  const r = repoData[p.repo.toLowerCase()];
  if (!r) return null;
  if (!r.ready?.totalCount) return { reason: `no open ticket with ${cfg.READY_LABEL}` };
  return null;
};

// --- Free start times in the time windows from PLANNING_TIMES, at most one planning session per day
const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const hm = s => String(s).split(':').map(Number);
const duration = { minutes: cfg.PLANNING_MINUTES };
const freeSlots = (taken, skipDays) => {
  const earliest = now.plus({ hours: cfg.LEAD_HOURS });
  const out = [];
  for (let i = 0; i <= cfg.HORIZON_DAYS; i++) {
    const day = now.startOf('day').plus({ days: i });
    if (skipDays.has(day.toISODate())) continue;
    for (const [from, to] of (cfg.PLANNING_TIMES[DAYS[day.weekday - 1]] || [])) {
      const [sh, sm] = hm(from), [eh, em] = hm(to);
      const end = day.set({ hour: eh, minute: em });
      for (let s = day.set({ hour: sh, minute: sm }); s.plus(duration) <= end; s = s.plus({ minutes: cfg.GRID_MINUTES })) {
        const e = s.plus(duration);
        if (s < earliest || taken.some(([bs, be]) => bs < e && be > s)) continue;
        out.push(s);
      }
    }
  }
  return out;
};
const pick = a => a[Math.floor(Math.random() * a.length)];
const fmt = s => `${s.setLocale('en').toFormat('ccc d LLL HH:mm')}–${s.plus(duration).toFormat('HH:mm')}`;
const cb = (a, p, s) => `s|${a}|${p.key}|${Math.floor(s.toSeconds() / 60)}`;
const bytes = s => encodeURIComponent(s).replace(/%[0-9A-F]{2}/g, 'x').length;
// The message starts with [key] so that CodeBot - Chat assigns a reply to it to the project
const proposal = (p, s, b) => ({
  text: `[${p.key}] 🧭 Planning session for ${p.name}\nProposal: ${fmt(s)}\nReason: ${b.reason}`,
  link_preview_options: { is_disabled: true },
  reply_markup: { inline_keyboard: [[
    { text: '✅ Schedule', callback_data: cb('e', p, s) },
    { text: '🔀 Another slot', callback_data: cb('a', p, s) },
    { text: '⏭ Skip', callback_data: cb('x', p, s) } ]] },
});

// --- Button under a proposal
if (inp.mode === 'callback') {
  const ack = (text = '') => tg('answerCallbackQuery', { callback_query_id: inp.queryId, text });
  const edit = payload => tg('editMessageText', { chat_id: inp.chatId, message_id: inp.messageId, link_preview_options: { is_disabled: true }, ...payload });
  const p = all.find(x => x.key === inp.key);
  if (!p) return [ack(), edit({ text: `[${inp.key}] ⚠️ The project is no longer in codebot_projects.` })];
  if (inp.action === 'x') {
    sd.pause[p.key] = now.plus({ days: cfg.SKIP_DAYS }).toISO();
    return [ack(), edit({ text: `[${p.key}] ⏭ Planning session for ${p.name} skipped. Next proposal in ${cfg.SKIP_DAYS} days at the earliest, or with /plan.` })];
  }
  if (calError) return [ack('The calendar is not readable right now.')];
  if (planned.has(p.repo.toLowerCase()))
    return [ack(), edit({ text: `[${p.key}] ✅ There is already a planning session for ${p.name} in the calendar.` })];
  const b = need(p) || { reason: 'requested by you' };
  const start = DateTime.fromSeconds(inp.startMin * 60, { zone: tz });
  const free = freeSlots(busy, sessionDays);
  if (inp.action === 'e' && free.some(s => s.toMillis() === start.toMillis())) {
    return [ack('Scheduling it.'), { json: {
      kind: 'event', key: p.key, name: p.name, label: fmt(start),
      start: start.toISO(), end: start.plus(duration).toISO(),
      summary: `🧭 Planning: ${p.name}`,
      description: `Create the next tickets with the label ${cfg.READY_LABEL}.\nhttps://github.com/${p.repo}\n\nScheduled by Code-Bot after your confirmation. Feel free to move or delete it at any time.\ncodebot-key: codebot-plan:${p.repo}`,
      editUrl: api('editMessageText'), chatId: inp.chatId, messageId: inp.messageId,
    } }];
  }
  // Another slot was requested, or the proposed one is no longer free
  const others = free.filter(s => s.toMillis() !== start.toMillis());
  if (!others.length) return [ack(`No other free slot in the next ${cfg.HORIZON_DAYS} days.`)];
  return [ack(inp.action === 'e' ? 'That slot is no longer free. Here is another one.' : ''), edit(proposal(p, pick(others), b))];
}

// --- Daily run and /plan: one proposal per project that needs planning and has no future planning session
if (calError) return [info(`⚠️ Planning: your own calendar could not be read (${calError}).`)];
const prio = { High: 3, Medium: 2, Low: 1 };
const projects = all.filter(p => cfg.STATUS.includes(p.status) && /^[\w.-]+\/[\w.-]+$/.test(p.repo))
  .sort((a, b) => (prio[b.prio] || 0) - (prio[a.prio] || 0));
const out = [], taken = [...busy], usedDays = new Set(sessionDays), noSlot = [], noRepo = [], tooLong = [];
for (const p of projects) {
  if (planned.has(p.repo.toLowerCase())) continue;
  if (!repoData[p.repo.toLowerCase()]) { noRepo.push(p.key); continue; }
  const b = need(p);
  if (!b) continue;
  if (inp.mode === 'run' && sd.pause[p.key] && DateTime.fromISO(sd.pause[p.key]) > now) continue;
  const free = freeSlots(taken, usedDays);
  if (!free.length) { noSlot.push(p.key); continue; }
  const s = pick(free);
  if (bytes(cb('e', p, s)) > 64) { tooLong.push(p.key); continue; }
  taken.push([s, s.plus(duration)]);
  usedDays.add(s.toISODate());
  out.push(tg('sendMessage', { chat_id: cfg.CHAT_ID, ...proposal(p, s, b) }));
  sd.pause[p.key] = now.plus({ days: cfg.REPROPOSE_DAYS }).toISO();
}
const notes = [];
if (noSlot.length) notes.push(`No free slot in the next ${cfg.HORIZON_DAYS} days for: ${noSlot.join(', ')}`);
if (noRepo.length) notes.push(`GitHub returned no data for: ${noRepo.join(', ')} (check the repo in codebot_projects)`);
if (tooLong.length) notes.push(`Key too long for buttons: ${tooLong.join(', ')}`);
if (out.length && listError) notes.push(`The calendar list was not readable (${listError}); only your own calendar was checked`);
if (out.length && unreadable.length) notes.push(`Unreadable calendars, not checked for overlaps there: ${unreadable.join(', ')}`);
if (notes.length) out.push(info(`⚠️ Planning\n${notes.join('\n')}`));
if (inp.mode === 'plan' && !out.length) out.push(info('🧭 No project needs a planning session right now.'));
return out;

// The message with the proposal then shows the result; the buttons disappear
const t = $('Event only').first().json;
const error = $input.first().json.error;
if (!error) delete ($getWorkflowStaticData('global').pause || {})[t.key];
const text = error
  ? `[${t.key}] ⚠️ The planning session for ${t.name} could not be scheduled: ${typeof error === 'string' ? error : error.message || 'error'}`
  : `[${t.key}] ✅ Planning session for ${t.name} scheduled: ${t.label}`;
return [{ json: { kind: 'tg', url: t.editUrl, payload: { chat_id: t.chatId, message_id: t.messageId, text, link_preview_options: { is_disabled: true } } } }];
